g_id to_gid(d_id d, t_id t) {
    return d * Tasks + t;
}

time_t new_sporadic_period;

void completed() {
  complete[gid][tid] = true;

  load[task[gid][tid].curr_resource] -= task[gid][tid].wcet;
}

time_t convertToTime(double x) {
    time_t result = 0;

    if (x >= 0) {
        while (x >= result) {
            result = result + 1;
        }
    } else {
        while (x <= result) {
            result = result - 1;
        }
    }

    return result;
}

void new_period() {

  complete[gid][tid] = false;

 /* if (dag[gid].sporadic == true)
  {
      int i = 0;
      // for (i = 0; i < dag[0].
// completed[]
      new_sporadic_period = task[gid][tid].min_period + 1;// convertToTime(random(Sporadic_Interval) + 1);
      task[gid][tid].max_period = task[gid][tid].min_period = new_sporadic_period;
  }*/

  task[gid][tid].curr_resource = -1;
}

time_t initialOffset() { return task[gid][tid].initial_offset; }
time_t minPeriod() { return task[gid][tid].min_period; }
time_t maxPeriod() { return task[gid][tid].max_period; }
time_t offset() { return task[gid][tid].offset; }
time_t deadline() { return task[gid][tid].deadline; }
time_t BCET() { return task[gid][tid].bcet; }
time_t WCET() { return task[gid][tid].wcet; }
time_t priotiry() { return task[gid][tid].pri; }
r_id resource() { return task[gid][tid].curr_resource; }

int[0,1] isRunning() {
  return (buffer[resource()].element[0] == tid? 1 : 0);
/*
  int i;
  for (i = 0; i < Procs-1; i++)
  {
    r_id r = task[gid][tid].resources[i];
    if (buffer[r].length > 0 && buffer[r].element[0] == tid)
    {
      return 1;
    }
  }
  return 0;
*/
}

int debug_resource_found= -1;

clock soonest_release;
clock remaining;

int FindEdge(t_id pred, t_id succ)
{
    int i;

    for (i = 0; i < Tasks; i++)
    {
        if (task[gid][i].type == 1)
        {
            if (cons[gid][pred][i] > 0 && prod[gid][i][succ] > 0)
            {
                return i;
            }
        }
    }

    return -1;
}

void CheckPredecessorsOfTask()
{
    int pred;

    for (pred = 0; pred < Tasks; pred++)
    {
        if (cons[gid][pred][tid] > 0)
        {
            int pred_res = task[gid][pred].curr_resource;
            int this_res = task[gid][tid].curr_resource;

            if (pred_res != -1 &&
                this_res != -1 &&
                this_res != pred_res)
            {
                int edge = FindEdge(pred, tid);
                if (edge >= 0)
                {
                    task[gid][edge].curr_resource = bus[0];
                }
            }
        }
    }
}

bool FindBestProcessor()
{
    int best_len = BufferSize +1;
    bool ret = false;
    int i, j;
    bool first_candidate = true;
    t_id best_running;

    soonest_release = MaxTime + 1;

    for (i = 0; i < Procs-1; i++)
    {
        r_id r = task[gid][tid].resources[i];

        if (buffer[r].length < best_len &&
            task[gid][tid].curr_resource == -1 &&
            load[r] + task[gid][tid].wcet <= load_limit[r])
        {
            best_len = buffer[r].length;
            task[gid][tid].curr_resource = debug_resource_found = r;
            load[r] += task[gid][tid].wcet;
            ret = true;
        }
    }

    for (i = 0; i < Procs-1; i++)
    {
        r_id r = task[gid][tid].resources[i];
        t_id running = buffer[r].element[0];

        if (buffer[r].length < best_len &&
            task[gid][tid].curr_resource == -1)
        {
            if (first_candidate ||
                time[gid][running] > time[gid][best_running])
            {
                best_len = buffer[r].length;
                task[gid][tid].curr_resource = debug_resource_found = r;
                load[r] += task[gid][tid].wcet;
                best_running = running;
                ret = true;
                first_candidate = false;
            }
        }
    }

    return ret;
}

void SearchIdleResouce()
{
    bool best_resource_found;

    best_resource_found = FindBestProcessor();
    /**
     * check if it makes sense to migrate the task
     * to another processor, if so, consider the edge task
     */
    if (best_resource_found)
    {
        CheckPredecessorsOfTask();
    }
}

void insert_task_in_buffer() {
  d_id d = param.dag;
  t_id t = param.task;
  r_id r = param.resource;
  int place = (param.preempt ? 0 : 1);

  // Find out where to put the task
  while ( place < buffer[r].length && task[d][buffer[r].element[place]].pri >= task[d][t].pri ) {
    place++;
  }
  insert_at(place,t,r);
}

int[0,Tasks] place;
t_id tid;
r_id rid;
bool preempt;

void readParameters() {
  tid = param.task; rid = param.resource; preempt = param.preempt;
}

void resetVars() {
  place = tid = rid = 0;
}

nta.system:
//Task id, res. ass., bcet, wcet, deadline, offset, period
// Resource id, preemptive, policy
P0  = Resource(0, false,FPS);
P1  = Resource(1, false,FPS);
// P2  = Resource(2, false,FPS);
Bus = Resource(2, false,FIFO);

system Task2, P0, P1, Bus, Scheduler, Policy_FPS, Policy_FIFO;
